(()=>{

const $ = id => document.getElementById(id);
const A = "/assets/cinorev/pattu/a/";
const WA = FMI.phone;           /* the family's WhatsApp in a real invitation */
const TARGET = FMI.target;
const calm = FMI.reduceMotion || matchMedia("(prefers-reduced-motion: reduce)").matches;
const params = new URLSearchParams(FMI.search);
const preview = false;

/* the three celebrations, each in its own saree */
const EV = FMI.events([
  { id: "nichayathartham", name: "Nichayathartham", sub: "The engagement", img: "pink", c: "#D6336C", day: "Saturday, 29 May 2027", t: "11:00 AM", w: "Sri Lakshmi Kalyana Mandapam<br>Mylapore, Chennai", note: "Lunch on banana leaf follows", dress: "Pinks and pastels", map: "Mylapore+Chennai", cal: "20270529T053000Z/20270529T073000Z" },
  { id: "reception", name: "Reception", sub: "Saturday evening", img: "blue", c: "#0F7A7A", day: "Saturday, 29 May 2027", t: "7:00 PM onwards", w: "Park Hyatt Chennai<br>Guindy, Chennai", note: "Dinner will be served", dress: "Jewel tones", map: "Park+Hyatt+Chennai", cal: "20270529T133000Z/20270529T170000Z" },
  { id: "muhurtham", name: "Muhurtham", sub: "Sunday morning", img: "red", c: "#B3162A", day: "Sunday, 30 May 2027", t: "9:00 to 10:30 AM", w: "Sri Lakshmi Kalyana Mandapam<br>Mylapore, Chennai", note: "Lunch on banana leaf follows", dress: "Traditional silks", map: "Mylapore+Chennai", cal: "20270530T033000Z/20270530T050000Z" }
]);

/* guest name from ?to=Kumar-Family */
let guest = "";
try {
  guest = (params.get("to") || "").replace(/[-_+]+/g, " ").replace(/\s+/g, " ").trim().slice(0, 40);
  guest = guest.split(" ").map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(" ");
} catch (e) {}
if (guest) {
  ["dear", "g-dear"].forEach(id => { $(id).textContent = "Dear " + guest + ","; $(id).hidden = false; });
  $("r-name").value = guest;
  document.title = "Dear " + guest + " · Pranav & Harini's Wedding";
}

/* sounds, made in the browser */
let actx, noiseBuf;
function ac(){ try { actx = actx || new (window.AudioContext || window.webkitAudioContext)(); if (actx.state === "suspended") actx.resume(); } catch (e) {} return actx; }
const live = () => actx && actx.state === "running";
function noise(when, dur, type, freq, q, gain, sweep){
  const c = ac(); if (!c) return;
  try {
    if (!noiseBuf) { noiseBuf = c.createBuffer(1, c.sampleRate * 2, c.sampleRate); const d = noiseBuf.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1; }
    const t0 = c.currentTime + (when || 0), s = c.createBufferSource(); s.buffer = noiseBuf;
    const f = c.createBiquadFilter(); f.type = type; f.frequency.setValueAtTime(freq, t0); f.Q.value = q;
    if (sweep) f.frequency.exponentialRampToValueAtTime(sweep, t0 + dur);
    const g = c.createGain(); g.gain.setValueAtTime(.0001, t0); g.gain.linearRampToValueAtTime(gain, t0 + Math.min(.04, dur * .3)); g.gain.exponentialRampToValueAtTime(.0001, t0 + dur);
    s.connect(f); f.connect(g); g.connect(c.destination); s.start(t0, Math.random()); s.stop(t0 + dur + .05);
  } catch (e) {}
}
function chime(base, gain, when){
  const c = ac(); if (!c) return;
  try {
    const t0 = c.currentTime + .02 + (when || 0), out = c.createGain(); out.gain.value = gain || .05; out.connect(c.destination);
    [[1, 1, 2], [2, .35, 1.4], [3, .14, .9], [4.2, .06, .5]].forEach(([r, g, d]) => {
      const o = c.createOscillator(); o.type = "sine"; o.frequency.value = base * r;
      const v = c.createGain(); v.gain.setValueAtTime(0, t0); v.gain.linearRampToValueAtTime(g, t0 + .008); v.gain.exponentialRampToValueAtTime(.0001, t0 + d);
      o.connect(v); v.connect(out); o.start(t0); o.stop(t0 + d + .05);
    });
  } catch (e) {}
}
const clack = w => { noise(w || 0, .07, "bandpass", 700, 2, .5); noise((w || 0) + .01, .05, "lowpass", 300, .7, .4); };
const whoosh = w => noise(w || 0, .45, "bandpass", 600, .9, .35, 3200);
const silk = () => noise(0, .7, "highpass", 2400, .5, .12);

/* music: starts with the shuttle; the button hides itself if no song is loaded */
const music = $("music"), mBtn = $("music-btn");
let musicWanted = false, noMusic = false;
music.addEventListener("error", () => { noMusic = true; mBtn.hidden = true; });
function paintMusic(){ mBtn.classList.toggle("on", musicWanted); mBtn.setAttribute("aria-pressed", musicWanted); mBtn.setAttribute("aria-label", musicWanted ? "Pause music" : "Play music"); }
function setMusic(on){
  musicWanted = on;
  if (on && !noMusic) { music.volume = .75; const p = music.play(); if (p) p.catch(() => { musicWanted = false; paintMusic(); }); }
  else music.pause();
  paintMusic();
}
mBtn.addEventListener("click", () => setMusic(!musicWanted));
document.addEventListener("visibilitychange", () => { if (document.hidden) music.pause(); else if (musicWanted && !noMusic) music.play().catch(() => {}); });

/* petals and jasmine */
const cv = $("fx"), cx = cv.getContext("2d");
let bits = [], fxRun = false, fxLast = 0;
function sizeCv(){ const d = Math.min(2, devicePixelRatio || 1); cv.width = innerWidth * d; cv.height = innerHeight * d; cx.setTransform(d, 0, 0, d, 0, 0); }
sizeCv(); addEventListener("resize", sizeCv);
const KINDS = [["petal", "#C8102E"], ["petal", "#E0405A"], ["petal", "#B3122E"], ["jas", "#FFFDF4"], ["jas", "#FFFDF4"], ["gold", "#F3DC97"]];
function bit(x, y, vx, vy){ const k = KINDS[Math.floor(Math.random() * KINDS.length)]; return { x, y, vx, vy, k: k[0], c: k[1], r: Math.random() * 6.3, vr: (Math.random() - .5) * 8, s: 1 + Math.random() * .5, ph: Math.random() * 6.3 }; }
function burst(x, y, n, power){ if (calm) return; for (let i = 0; i < n; i++) { const a = -Math.PI / 2 + (Math.random() - .5) * 2.6, s = power * (.35 + Math.random() * .75); bits.push(bit(x, y, Math.cos(a) * s, Math.sin(a) * s)); } start(); }
function start(){ if (bits.length > 500) bits.splice(0, bits.length - 500); if (!fxRun) { fxRun = true; fxLast = performance.now(); requestAnimationFrame(step); } }
function step(t){
  const dt = Math.min(.033, (t - fxLast) / 1000); fxLast = t;
  cx.clearRect(0, 0, innerWidth, innerHeight);
  bits = bits.filter(b => b.y < innerHeight + 30);
  for (const b of bits) {
    b.vy = Math.min(b.vy + 480 * dt, 150); b.vx *= .985;
    b.x += (b.vx + Math.sin(t / 380 + b.ph) * 30) * dt; b.y += b.vy * dt; b.r += b.vr * dt;
    cx.save(); cx.translate(b.x, b.y); cx.rotate(b.r); cx.fillStyle = b.c;
    if (b.k === "petal") { cx.scale(1, Math.cos(b.r * 1.3) * .5 + .7); cx.beginPath(); cx.ellipse(0, 0, 3.6 * b.s, 5.4 * b.s, 0, 0, 6.3); cx.fill(); }
    else if (b.k === "gold") { cx.fillRect(-1, -4, 2, 8); }
    else { for (let i = 0; i < 5; i++) { cx.rotate(1.2566); cx.beginPath(); cx.ellipse(0, -2.6 * b.s, 1.5 * b.s, 2.6 * b.s, 0, 0, 6.3); cx.fill(); } }
    cx.restore();
  }
  if (bits.length) requestAnimationFrame(step); else { fxRun = false; cx.clearRect(0, 0, innerWidth, innerHeight); }
}

/* gate: drag the shuttle across the warp, or tap the button */
const gate = $("gate"), shut = $("shuttle");
let opened = false, drag = null;
function finish(){
  if (opened) return; opened = true;
  ac(); setMusic(true); if (!noMusic) mBtn.hidden = false;
  gate.classList.add("done"); gate.style.setProperty("--gx", 1);
  whoosh(); clack(.5); [659.25, 830.6, 987.8, 1318.5].forEach((f, i) => chime(f, .045, .55 + i * .09));
  setTimeout(() => { document.body.classList.remove("locked"); gate.classList.add("gone"); update(); }, calm ? 200 : 1300);
  setTimeout(() => { gate.hidden = true; }, calm ? 900 : 2400);
}
shut.addEventListener("pointerdown", e => { if (opened) return; ac(); drag = { x: e.clientX, g: 0, id: e.pointerId }; gate.classList.add("drag"); try { shut.setPointerCapture(e.pointerId); } catch (er) {} });
shut.addEventListener("pointermove", e => {
  if (!drag || e.pointerId !== drag.id) return;
  const span = Math.max(80, innerWidth - 240), g = Math.min(1, Math.max(0, (e.clientX - drag.x) / span));
  drag.g = g; gate.style.setProperty("--gx", g.toFixed(3));
  if (g > .62) { drag = null; finish(); }
});
function release(){ if (!drag) return; const moved = drag.g; drag = null; if (moved < .04) finish(); else { gate.style.setProperty("--gx", 0); gate.classList.remove("drag"); } }
shut.addEventListener("pointerup", release); shut.addEventListener("pointercancel", release);
shut.addEventListener("keydown", e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); finish(); } });
$("open").addEventListener("click", finish);
if (preview) { gate.hidden = true; document.body.classList.remove("locked"); }

/* zari shimmer: follows the finger, the mouse, or the tilt of the phone; drifts on its own otherwise */
const wStage = $("weave-stage"), weave = $("s-weave");
let mx = .5, target = .5, lastInput = 0, weaveVis = false;
wStage.addEventListener("pointermove", e => { const r = wStage.getBoundingClientRect(); target = (e.clientX - r.left) / r.width; lastInput = performance.now(); }, { passive: true });
addEventListener("deviceorientation", e => { if (e.gamma == null) return; target = Math.min(1, Math.max(0, .5 + e.gamma / 50)); lastInput = performance.now(); }, { passive: true });
function shimmer(t){
  if (weaveVis && !calm) {
    if (t - lastInput > 2500) target = .5 + Math.sin(t / 1600) * .55;
    mx += (target - mx) * .08; wStage.style.setProperty("--mx", mx.toFixed(3));
  }
  requestAnimationFrame(shimmer);
}
requestAnimationFrame(shimmer);

/* scroll engine: weaving, the shuttle runs along the edge */
const root = document.documentElement;
let ticking = false, lastPass = -1;
function update(){
  const vh = innerHeight, r = weave.getBoundingClientRect();
  weaveVis = r.bottom > 0 && r.top < vh;
  let p = calm ? 0 : Math.min(1, Math.max(0, -r.top / Math.max(1, r.height - vh)));
  weave.style.setProperty("--p", p.toFixed(4));
  const wv = Math.min(1, p / .44), passes = wv * 16, k = Math.floor(passes), f = passes - k;
  weave.style.setProperty("--sx", (k % 2 ? 1 - f : f).toFixed(3));
  if (k !== lastPass && wv > 0 && wv < 1) { if (live() && lastPass >= 0) clack(); lastPass = k; }
  const max = root.scrollHeight - vh;
  root.style.setProperty("--gp", max > 0 ? (scrollY / max).toFixed(4) : 0);
  ticking = false;
}
addEventListener("scroll", () => { if (!ticking) { ticking = true; requestAnimationFrame(update); } }, { passive: true });
addEventListener("resize", update);
update();

/* reveal on view */
const io = "IntersectionObserver" in window ? new IntersectionObserver(es => es.forEach(e => {
  if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); }
}), { threshold: .12 }) : null;
document.querySelectorAll(".rv").forEach(el => io ? io.observe(el) : el.classList.add("in"));

/* the silk-shop flick: the chosen saree is thrown open across the counter */
const throwEl = $("throw"), spots = [...document.querySelectorAll(".spot")], tabs = [...document.querySelectorAll(".tab")];
const esc = s => s.replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
let cur = -1;
function openEv(i, quiet){
  const e = EV[i]; cur = i;
  spots.forEach((s, k) => s.classList.toggle("on", k === i));
  tabs.forEach((t, k) => t.setAttribute("aria-selected", k === i));
  throwEl.style.setProperty("--bg", 'url("' + A + e.img + '.webp")');
  throwEl.style.setProperty("--ox", (16.5 + i * 33.5) + "%");
  throwEl.style.setProperty("--cl", (i * 33.4) + "%"); throwEl.style.setProperty("--cr", ((2 - i) * 33.4) + "%");
  throwEl.style.setProperty("--sk", (i - 1) * 10 + "deg");
  throwEl.innerHTML = '<div class="ecard"><p class="lbl">' + esc(e.sub) + '</p><h3 class="zari">' + esc(e.name) + '</h3><p class="d">' + esc(e.day) + '</p><p class="t">' + esc(e.t) + '</p><p class="w">' + e.w + '</p><p class="w" style="font-size:1rem">' + esc(e.note) + '</p>' +
    '<p class="dc"><i style="--c:' + e.c + '"></i>Dress: ' + esc(e.dress) + '</p>' +
    '<div class="acts"><a class="pill solid" href="https://www.google.com/maps/search/?api=1&query=' + e.map + '" target="_blank" rel="noopener"><svg aria-hidden="true"><use href="#pin"/></svg>Directions</a>' +
    '<a class="pill" data-cal="' + e.id + '" href="/pranav-harini/' + e.id + '.ics"><svg aria-hidden="true"><use href="#cal"/></svg>Add to calendar</a></div></div>';
  calLinks(throwEl);
  fitTitle();
  throwEl.classList.remove("fly", "shown"); void throwEl.offsetWidth;
  if (!calm) throwEl.classList.add("fly");
  requestAnimationFrame(() => throwEl.classList.add("shown"));
  if (!quiet && live()) { silk(); whoosh(0); }
}
function fitTitle(){
  const h = throwEl.querySelector("h3"); if (!h) return;
  h.style.fontSize = ""; let fs = parseFloat(getComputedStyle(h).fontSize);
  while (h.scrollWidth > h.clientWidth + 1 && fs > 20) { fs -= 1; h.style.fontSize = fs + "px"; }
}
addEventListener("resize", fitTitle);
if (document.fonts) document.fonts.ready.then(fitTitle);
spots.forEach(s => s.addEventListener("click", () => { ac(); openEv(+s.dataset.ev); }));
tabs.forEach(t => t.addEventListener("click", () => { ac(); openEv(+t.dataset.ev); }));
if ("IntersectionObserver" in window) new IntersectionObserver(([e], o) => { if (e.isIntersecting && cur < 0) { setTimeout(() => { if (cur < 0) openEv(0, true); }, 900); o.disconnect(); } }, { threshold: .35 }).observe($("counter"));
else openEv(0, true);

/* maalai maatral: three exchanges */
const gl = $("gl-photo"), glDots = [...$("gl-dots").children];
let swaps = 0;
function exchange(){
  ac();
  if (swaps >= 3) { swaps = 0; glDots.forEach(d => d.classList.remove("on")); $("gl-msg").textContent = ""; $("gl-btn").textContent = "Exchange the garlands"; gl.classList.remove("flip"); return; }
  swaps++; gl.classList.toggle("flip"); glDots[swaps - 1].classList.add("on");
  chime([784, 880, 1046.5][swaps - 1], .05);
  if (swaps === 3) {
    $("gl-msg").textContent = "Three times, done! May you always win each other's hearts.";
    $("gl-btn").textContent = "Once more";
    const r = gl.getBoundingClientRect(); burst(r.left + r.width / 2, r.top + r.height * .3, 90, 520);
    [659.25, 830.6, 987.8, 1318.5].forEach((f, i) => chime(f, .045, .2 + i * .09));
  } else $("gl-msg").textContent = ["", "One!", "Two!"][swaps];
}
gl.addEventListener("click", exchange); $("gl-btn").addEventListener("click", exchange);

/* countdown */
const cells = {}; document.querySelectorAll("#count b").forEach(b => cells[b.dataset.u] = b);
function tick(){
  let s = Math.floor((TARGET - Date.now()) / 1000);
  if (s <= 0) { $("count").innerHTML = '<p style="grid-column:1/-1;font-size:1.4rem;font-style:italic">Pranav and Harini are married. Thank you for your blessings!</p>'; return; }
  const d = Math.floor(s / 86400); s -= d * 86400;
  const h = Math.floor(s / 3600); s -= h * 3600;
  const m = Math.floor(s / 60); s -= m * 60;
  cells.d.textContent = d;
  cells.h.textContent = String(h).padStart(2, "0");
  cells.m.textContent = String(m).padStart(2, "0");
  cells.s.textContent = String(s).padStart(2, "0");
  setTimeout(tick, 1000 - Date.now() % 1000);
}
tick();

/* calendar: Apple devices open the .ics, others get Google Calendar */
function calLinks(scope){
  if (/iPhone|iPad|iPod|Macintosh/.test(navigator.userAgent)) return;
  scope.querySelectorAll("[data-cal]").forEach(a => {
    const e = EV.find(x => x.id === a.dataset.cal);
    a.href = "https://calendar.google.com/calendar/render?action=TEMPLATE&text=" + encodeURIComponent("Pranav & Harini · " + e.name) + "&dates=" + e.cal + "&location=" + encodeURIComponent(e.w.replace("<br>", ", ")) + "&details=" + encodeURIComponent("Dress: " + e.dress + ". Invitation: https://findmyinvite.com/");
    a.target = "_blank"; a.rel = "noopener";
  });
}

/* rsvp */
let guests = 2;
$("g-minus").addEventListener("click", () => { guests = Math.max(1, guests - 1); $("g-count").textContent = guests; });
$("g-plus").addEventListener("click", () => { guests = Math.min(20, guests + 1); $("g-count").textContent = guests; });
const form = $("rsvp-form");
form.addEventListener("change", () => {
  $("att-yes").style.display = form.querySelector("input[name=att]:checked").value === "yes" ? "grid" : "none";
});
form.addEventListener("submit", e => {
  e.preventDefault();
  const name = $("r-name").value.trim();
  if (!name) { $("r-err").hidden = false; $("r-name").focus(); return; }
  $("r-err").hidden = true;
  const yes = form.querySelector("input[name=att]:checked").value === "yes";
  const lines = ["RSVP · Pranav & Harini's Wedding ✨", "", "Name: " + name, "Attending: " + (yes ? "Yes, happily" : "Sorry, can't make it")];
  if (yes) {
    lines.push("For: " + ([...form.querySelectorAll("input[name=fn]:checked")].map(i => i.value).join(", ") || "Not sure yet"));
    lines.push("Guests: " + guests);
  }
  const w = $("r-msg").value.trim(); if (w) lines.push("Wishes: " + w);
  const url = "https://wa.me/" + WA + "?text=" + encodeURIComponent(lines.join("\n"));
  const win = FMI.open(url, "_blank"); if (!win) FMI.open(url);
});

/* share */
function toast(t){ const el = $("toast"); el.textContent = t; el.hidden = false; clearTimeout(toast.t); toast.t = setTimeout(() => el.hidden = true, 2200); }
$("share").addEventListener("click", async () => {
  const url = location.origin + FMI.instanceKey;
  try {
    if (navigator.share) { await FMI.share({ title: "Pranav & Harini · Woven in silk", text: "You're invited to Pranav & Harini's wedding on 30 May 2027 in Chennai", url }); return; }
    await FMI.copyLink(url); toast("Invitation link copied");
  } catch (e) { if (e && e.name !== "AbortError") toast(url); }
});

FMI.ready();
})();
